schema:
{
  "description": "Registra la fattura nel gestionale: compila i campi e scegli per ognuno il metodo con cui lo otterresti in Content Understanding.",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "NumeroFattura": {
        "type": "string",
        "method": "extract",
        "description": "Il numero dopo \"FATTURA N.\"."
      },
      "DataFattura": {
        "type": "date",
        "method": "extract",
        "description": "Data della fattura."
      },
      "CondizioniPagamento": {
        "type": "string",
        "method": "extract",
        "description": "Condizioni di pagamento, per esempio \"60 gg d.f.\"."
      },
      "Fornitore": {
        "type": "string",
        "method": "extract",
        "description": "Ragione sociale del fornitore."
      },
      "ModalitaPagamento": {
        "type": "string",
        "method": "classify",
        "description": "C'è scritto \"bonifico\": è una scelta da un elenco chiuso.",
        "enum": [
          "bonifico",
          "riba",
          "carta",
          "contanti"
        ]
      }
    }
  }
}
